若$\vec{a}$，$\vec{b}$为非零向量，$\vec{e}$为单位向量，则有

(1) $\vec{e} \cdot \vec{a} = \vec{a} \cdot \vec{e} = |\vec{a}| \cos \langle \vec{a}, \vec{e} \rangle$;

(2) $\vec{a} \perp \vec{b} \Leftrightarrow \vec{a} \cdot \vec{b} = 0$;

(3) $\vec{a} \cdot \vec{b} = \begin{cases} |\vec{a}| |\vec{b}| \left( \vec{a} \text{与}\vec{b} \text{同向}\right), & \vec{a} \cdot \vec{a} = |\vec{a}|^2, \\ -|\vec{a}| |\vec{b}| \left( \vec{a} \text{与}\vec{b} \text{反向}\right) \end{cases}$;

(4) $\cos \langle \vec{a}, \vec{b} \rangle = \frac{\vec{a} \cdot \vec{b}}{|\vec{a}||\vec{b}|}$;

(5) $|\vec{a} \cdot \vec{b}| \leqslant |\vec{a}||\vec{b}|$.

\begin{align}
(1)\quad \vec{a} \cdot \vec{b} &= \vec{b} \cdot \vec{a}; \\
(2)\quad (\lambda \vec{a}) \cdot \vec{b} &= \lambda (\vec{a} \cdot \vec{b}) = \vec{a} \cdot (\lambda \vec{b}); \\
(3)\quad (\vec{a} + \vec{b}) \cdot \vec{c} &= \vec{a} \cdot \vec{c} + \vec{b} \cdot \vec{c}.
\end{align}

\begin{itemize}
  \item 对于任意两个向量 \(\vec{a}\) 和 \(\vec{b}\)，以及任意实数 \(\lambda\)，以下运算律成立：
    \begin{align}
    (1)\quad \vec{a} \cdot \vec{b} &= \vec{b} \cdot \vec{a}; \\
    (2)\quad (\lambda \vec{a}) \cdot \vec{b} &= \lambda (\vec{a} \cdot \vec{b}) = \vec{a} \cdot (\lambda \vec{b}); \\
    (3)\quad (\vec{a} + \vec{b}) \cdot \vec{c} &= \vec{a} \cdot \vec{c} + \vec{b} \cdot \vec{c}.
    \end{align}
\end{itemize}

\begin{itemize}
  \item 如果三个向量 \(\vec{a}\)，\(\vec{b}\)，\(\vec{c}\) 不共面，则对于空间中任意向量 \(\vec{p}\)，存在实数组 \(\{x, y, z\}\)，使得 \(\vec{p} = x\vec{a} + y\vec{b} + z\vec{c}\)。
\end{itemize}

\begin{itemize}
  \item 所有空间向量组成的集合是 \(\left\{\vec{p} \mid \vec{p} = x\vec{a} + y\vec{b} + z\vec{c}, x, y, z \in \mathbb{R}\right\}\)。这个集合可以看作是由向量 \(\vec{a}\)，\(\vec{b}\)，\(\vec{c}\) 生成的，\(\{\vec{a}, \vec{b}, \vec{c}\}\) 称为一个空间基底，\(\vec{a}\)，\(\vec{b}\)，\(\vec{c}\) 称为基向量。空间中任意三个不共面的向量都可以构成一个空间基底。
\end{itemize}

\begin{itemize}
  \item 设 \(\vec{e}_1\)，\(\vec{e}_2\)，\(\vec{e}_3\) 为有公共起点 \(O\) 的三个两两垂直的单位向量（称为单位正交基底），以 \(\vec{e}_1\)，\(\vec{e}_2\)，\(\vec{e}_3\) 的公共起点 \(O\) 为原点，分别以 \(\vec{e}_1\)，\(\vec{e}_2\)，\(\vec{e}_3\) 的方向为 \(x\) 轴，\(y\) 轴，\(z\) 轴的正方向建立空间直角坐标系 \(Oxyz\)。对于空间中任意一个向量 \(\vec{p}\)，存在有序实数组 \(\{x, y, z\}\)，使得 \(\vec{p} = x\vec{e}_1 + y\vec{e}_2 + z\vec{e}_3\)。此时，向量 \(\vec{p}\) 的坐标是点 \(P\) 在空间直角坐标系 \(Oxyz\) 中的坐标 \((x, y, z)\)。
\end{itemize}

\begin{itemize}
  \item 在空间中，取一定点 \(O\) 作为基点，那么空间中任意一点 \(P\) 的位置可以用向量 \(\overrightarrow{OP}\) 来表示，向量 \(\overrightarrow{OP}\) 称为点 \(P\) 的位置向量。
\end{itemize}

\begin{itemize}
  \item 空间中任意一条直线 \(l\) 的位置可以由 \(l\) 上一个定点 \(A\) 以及一个定方向确定。点 \(A\) 是直线 \(l\) 上一点，向量 \(\vec{a}\) 表示直线 \(l\) 的方向向量，则对于直线 \(l\) 上的任意一点 \(P\)，有 \(\overrightarrow{AP} = t\vec{a}\)，这样点 \(A\) 和向量 \(\vec{a}\) 不仅可以确定直线 \(l\) 的位置，还可以具体表示出直线 \(l\) 上的任意一点。
\end{itemize}

\begin{itemize}
  \item 空间中平面 \(\alpha\) 的位置可以由 \(\alpha\) 内的两条相交直线来确定。设这两条相交直线相交于点 \(O\)，它们的方向向量分别为 \(\vec{a}\)，\(\vec{b}\)。点 \(P\) 为平面 \(\alpha\) 上任意一点，存在有序实数对 \((x, y)\)，使得 \(\overrightarrow{OP} = x\vec{a} + y\vec{b}\)，这样点 \(O\) 与向量 \(\vec{a}\)，\(\vec{b}\) 就确定了平面 \(\alpha\) 的位置。
\end{itemize}

\begin{itemize}
  \item 直线 \(l\) 垂直于平面 \(\alpha\)，取直线 \(l\) 的方向向量 \(\vec{a}\)，则向量 \(\vec{a}\) 称为平面 \(\alpha\) 的法向量。
\end{itemize}

\begin{itemize}
  \item 对于空间中不重合的两条直线 \(a\)，\(b\)，它们的方向向量分别为 \(\vec{a}\)，\(\vec{b}\)：
    \begin{align}
    a \parallel b &\Leftrightarrow \vec{a} \parallel \vec{b} \Leftrightarrow \vec{a} = \lambda \vec{b} \quad (\lambda \in \mathbb{R}); \\
    a \perp b &\Leftrightarrow \vec{a} \perp \vec{b} \Leftrightarrow \vec{a} \cdot \vec{b} = 0.
    \end{align}
\end{itemize}

\begin{itemize}
  \item 设直线 \(a\) 的方向向量为 \(\vec{a}\)，平面 \(\alpha\) 的法向量为 \(\vec{n}\)，且 \(a \nsubseteq \alpha\)：
    \begin{align}
    a \parallel \alpha &\Leftrightarrow \vec{a} \parallel \alpha \Leftrightarrow \vec{a} \perp \vec{n} \Leftrightarrow \vec{a} \cdot \vec{n} = 0; \\
    a \perp \alpha &\Leftrightarrow \vec{a} \perp \alpha \Leftrightarrow \vec{a} \parallel \vec{n} \Leftrightarrow \vec{a} = \lambda \vec{n} \quad (\lambda \in \mathbb{R}).
    \end{align}
\end{itemize}

\begin{itemize}
  \item 对于空间中不重合的两个平面 \(\alpha\)，\(\beta\)，它们的法向量分别为 \(\vec{a}\)，\(\vec{b}\)：
    \begin{align}
    \alpha \parallel \beta &\Leftrightarrow \vec{a} \parallel \vec{b} \Leftrightarrow \vec{a} = \lambda \vec{b} \quad (\lambda \in \mathbb{R}); \\
    \alpha \perp \beta &\Leftrightarrow \vec{a} \perp \vec{b} \Leftrightarrow \vec{a} \cdot \vec{b} = 0.
    \end{align}
\end{itemize}

\begin{itemize}
  \item 设异面直线 \(a\)，\(b\) 的夹角为 \(\theta\)，它们的方向向量为 \(\vec{a}\)，\(\vec{b}\)，其夹角为 \(\varphi\)，则：
    \begin{align}
    \cos \theta = |\cos \varphi| = \frac{|\vec{a} \cdot \vec{b}|}{|\vec{a}| |\vec{b}|}.
    \end{align}
\end{itemize}

\begin{itemize}
  \item 设直线 \(l\) 的方向向量为 \(\vec{l}\)，平面 \(\alpha\) 的法向量为 \(\vec{n}\)，\(l\) 与 \(\alpha\) 所成的角为 \(\theta\)，\(\vec{l}\) 与 \(\vec{n}\) 的夹角为 \(\varphi\)，则：
    \begin{align}
    \sin \theta = |\cos \varphi| = \frac{|\vec{l} \cdot \vec{n}|}{|\vec{l}| |\vec{n}|}.
    \end{align}
\end{itemize}

\begin{itemize}
  \item 设 \(\vec{n}_1\)，\(\vec{n}_2\) 是二面角 \(\alpha-l-\beta\) 的两个面 \(\alpha\)，\(\beta\) 的法向量，则向量 \(\vec{n}_1\)，\(\vec{n}_2\) 的夹角（或其补角）就是二面角的平面角的大小。若二面角 \(\alpha-l-\beta\) 的平面角为 \(\theta\)，则：
    \begin{align}
    |\cos \theta| = \frac{|\vec{n}_1 \cdot \vec{n}_2|}{|\vec{n}_1| |\vec{n}_2|}.
    \end{align}
\end{itemize}

\begin{itemize}
  \item 点 \(A\) 与点 \(B\) 之间的距离可以转化为两点对应向量 \(\overrightarrow{AB}\) 的模 \(|\overrightarrow{AB}|\) 计算。
\end{itemize}

\begin{itemize}
  \item 在直线 \(l\) 上找一点 \(P\)，过定点 \(A\) 且垂直于直线 \(l\) 的向量为 \(\vec{n}\)，则定点 \(A\) 到直线 \(l\) 的距离为：
    \begin{align}
    d = |\overrightarrow{PA}| |\cos \langle \overrightarrow{PA}, \vec{n} \rangle| = \frac{|\overrightarrow{PA} \cdot \vec{n}|}{|\vec{n}|}.
    \end{align}
\end{itemize}

\begin{itemize}
  \item 点 \(P\) 是平面 \(\alpha\) 外一点，\(A\) 是平面 \(\alpha\) 内的一定点，\(\vec{n}\) 为平面 \(\alpha\) 的一个法向量，则点 \(P\) 到平面 \(\alpha\) 的距离为：
    \begin{align}
    d = |\overrightarrow{PA}| |\cos \langle \overrightarrow{PA}, \vec{n} \rangle| = \frac{|\overrightarrow{PA} \cdot \vec{n}|}{|\vec{n}|}.
    \end{align}
\end{itemize}

\begin{itemize}
  \item 导数的物理意义是瞬时速率。函数 \(y = f(x)\) 在 \(x = x_0\) 处的瞬时变化率是：
    \begin{align}
    \lim_{\Delta x \to 0} \frac{f(x_0 + \Delta x) - f(x_0)}{\Delta x},
    \end{align}
    我们称它为函数 \(y = f(x)\) 在 \(x = x_0\) 处的导数，记作 \(f'(x_0)\) 或 \(y'|_{x = x_0}\)，即：
    \begin{align}
    f'(x_0) = \lim_{\Delta x \to 0} \frac{f(x_0 + \Delta x) - f(x_0)}{\Delta x}.
    \end{align}
\end{itemize}

\begin{itemize}
  \item 导数的几何意义是曲线的切线。当点 \(P_n\) 趋近于 \(P\) 时，直线 \(PT\) 与曲线相切。割线 \(PP_n\) 的斜率是：
    \begin{align}
    k_n = \frac{f(x_n) - f(x_0)}{x_n - x_0},
    \end{align}
    当点 \(P_n\) 趋近于 \(P\) 时，函数 \(y = f(x)\) 在 \(x = x_0\) 处的导数就是切线 \(PT\) 的斜率 \(k\)，即：
    \begin{align}
    k = \lim_{\Delta x \to 0} \frac{f(x_n) - f(x_0)}{x_n - x_0} = f'(x_0).
    \end{align}
\end{itemize}

\begin{itemize}
  \item 当 \(x\) 变化时，\(f'(x)\) 便是 \(x\) 的一个函数，我们称它为 \(f(x)\) 的导函数。\(y = f(x)\) 的导函数有时也记作 \(y'\)，即：
    \begin{align}
    f'(x) = \lim_{\Delta x \to 0} \frac{f(x + \Delta x) - f(x)}{\Delta x}.
    \end{align}
\end{itemize}

\begin{itemize}
  \item \([f(x) \pm g(x)]' = f'(x) \pm g'(x)\)
  \item \([f(x) \cdot g(x)]' = f'(x) \cdot g(x) + f(x) \cdot g'(x)\)
  \item \(\left[\frac{f(x)}{g(x)}\right]' = \frac{f'(x) \cdot g(x) - f(x) \cdot g'(x)}{[g(x)]^2}\)
\end{itemize}

\begin{itemize}
  \item 若 \(y = f(u)\) 和 \(u = g(x)\)，则 \(y\) 可以表示为 \(x\) 的函数，即 \(y = f(g(x))\)，称为复合函数。复合函数的导数为：
    \[
    y' = f'(g(x)) \cdot g'(x)
    \]
\end{itemize}

\begin{itemize}
  \item 一般的，函数的单调性与其导数的正负有如下关系：
    \begin{enumerate}
      \item 如果 \(f'(x) > 0\)，那么函数 \(y = f(x)\) 在这个区间单调递增；
      \item 如果 \(f'(x) < 0\)，那么函数 \(y = f(x)\) 在这个区间单调递减。
    \end{enumerate}
\end{itemize}

\begin{itemize}
  \item 极值反映的是函数在某一点附近的大小情况。
  \item 求函数 \(y = f(x)\) 的极值的方法是：
    \begin{enumerate}
      \item 如果在 \(x_0\) 附近的左侧 \(f'(x) > 0\)，右侧 \(f'(x) < 0\)，那么 \(f(x_0)\) 是极大值；
      \item 如果在 \(x_0\) 附近的左侧 \(f'(x) < 0\)，右侧 \(f'(x) > 0\)，那么 \(f(x_0)\) 是极小值。
    \end{enumerate}
\end{itemize}

\begin{itemize}
  \item 求函数 \(y = f(x)\) 在 \([a, b]\) 上的最大值与最小值的步骤：
    \begin{enumerate}
      \item 求函数 \(y = f(x)\) 在 \((a, b)\) 内的极值；
      \item 将函数 \(y = f(x)\) 的各极值与端点处的函数值 \(f(a)\)，\(f(b)\) 比较，其中最大的是一个最大值，最小的是最小值。
    \end{enumerate}
\end{itemize}

\begin{itemize}
  \item 根据一类事物的部分对象具有某种性质，推出这类事物的所有对象都具有这种性质的推理，叫做归纳推理。归纳是从特殊到一般的过程，它属于合情推理。
\end{itemize}

\begin{itemize}
  \item 根据两类不同事物之间具有某些类似（或一致）性，推测其中一类事物具有与另外一类事物类似的性质的推理，叫做类比推理。
\end{itemize}

\begin{itemize}
  \item 找出两类事物的相似性或一致性；
  \item 用一类事物的性质去推测另一类事物的性质，得出一个明确的命题（猜想）；
  \item 一般的，事物之间的各个性质并不是孤立存在的，而是相互制约的。如果两个事物在某些性质上相同或相似，那么他们在另一些性质上也可能相同或类似，类比的结论可能是真的；
  \item 一般情况下，如果类比的相似性越多，相似的性质与推测的性质之间越相关，那么类比得出的命题越可靠。
\end{itemize}

\begin{itemize}
  \item 由一般性的命题推出特殊命题的过程，这种推理称为演绎推理。
\end{itemize}

\begin{itemize}
  \item 数学归纳法是一种递推的数学论证方法。
  \item 步骤：
    \begin{enumerate}
      \item 命题在 \(n = 1\)（或 \(n_0\)）时成立，这是递推的基础；
      \item 假设在 \(n = k\) 时命题成立；
      \item 证明 \(n = k + 1\) 时命题也成立。
    \end{enumerate}
  \item 完成这两步，就可以断定对任何自然数（或 \(n \geq n_0\)，且 \(n \in \mathbb{N}\)）结论都成立。
\end{itemize}

\begin{itemize}
  \item 反证法：
    \begin{itemize}
      \item 假设命题的结论不成立，然后通过逻辑推理得出矛盾，从而证明原命题成立。
    \end{itemize}
  \item 分析法：
    \begin{itemize}
      \item 从要证明的结论出发，逐步分析其成立的条件，直到找到已知或显然成立的条件为止。
    \end{itemize}
  \item 综合法：
    \begin{itemize}
      \item 从已知条件出发，通过逻辑推理和已知定理，逐步推导出要证明的结论。
    \end{itemize}
\end{itemize}

\begin{itemize}
  \item 复数：形如 \(a + bi\)（\(a \in \mathbb{R}\)，\(b \in \mathbb{R}\)）的数叫做复数，\(a\) 和 \(b\) 分别叫它的实部和虚部。
\end{itemize}

\begin{itemize}
  \item 复数 \(a + bi\)（\(a \in \mathbb{R}\)，\(b \in \mathbb{R}\)）中，当 \(b = 0\) 时，就是实数；当 \(b \neq 0\) 时，叫做虚数；当 \(a = 0\)，\(b \neq 0\) 时，叫做纯虚数。
\end{itemize}

\begin{itemize}
  \item 如果两个复数实部相等且虚部相等，就说这两个复数相等。
\end{itemize}

\begin{itemize}
  \item 当两个复数实部相等，虚部互为相反数时，这两个复数互为共轭复数。
\end{itemize}

\begin{itemize}
  \item 建立直角坐标系来表示复数的平面叫做复平面，x 轴叫做实轴，y 轴除去原点的部分叫做虚轴。
\end{itemize}

\begin{itemize}
  \item 两个实数可以比较大小，但两个复数如果不全是实数就不能比较大小。
\end{itemize}

\begin{itemize}
  \item 复数的加、减、乘、除按以下法则进行：
    \begin{itemize}
      \item 设 \(z_1 = a + bi\)，\(z_2 = c + di\)（\(a, b, c, d \in \mathbb{R}\)），则：
        \begin{align}
        (1)\quad z_1 \pm z_2 &= (a \pm c) + (b \pm d)i \\
        (2)\quad z_1 \cdot z_2 &= (ac - bd) + (ad + bc)i \\
        (3)\quad \frac{z_1}{z_2} &= \frac{(ac - bd) + (ad + bc)i}{c^2 + d^2} \quad (z_2 \neq 0)
        \end{align}
    \end{itemize}
\end{itemize}

\begin{itemize}
  \item \(|z_1 + z_2|^2 + |z_1 - z_2|^2 = 2(|z_1|^2 + |z_2|^2)\)
  \item \(z \cdot \overline{z} = |z|^2 = |\overline{z}|^2\)
  \item 若 \(z\) 为虚数，则 \(|z|^2 \neq z^2\)
\end{itemize}

\begin{itemize}
  \item \(z^m \cdot z^n = z^{m+n}\)
  \item \(\left(z^m\right)^n = z^{mn}\)
  \item \(\left(z_1 \cdot z_2\right)^n = z_1^n \cdot z_2^n\) (\(m, n \in \mathbb{R}\))
\end{itemize}

\begin{itemize}
  \item \(i^2 = -1\)
  \item \(i^3 = -i\)
  \item \(i^4 = 1\)
  \item \(i^n + i^{n+2} + i^{n+3} + i^{n+4} = 0\)
\end{itemize}

\begin{itemize}
  \item 做一件事情，完成它有 \(N\) 类办法，在第一类办法中有 \(M_1\) 种不同的方法，在第二类办法中有 \(M_2\) 种不同的方法，……，在第 \(N\) 类办法中有 \(M_N\) 种不同的方法，那么完成这件事情共有 \(M_1 + M_2 + \cdots + M_N\) 种不同的方法。
\end{itemize}

\begin{itemize}
  \item 做一件事情，完成它需要分成 \(N\) 个步骤，做第一步有 \(M_1\) 种不同的方法，做第二步有 \(M_2\) 种不同的方法，……，做第 \(N\) 步有 \(M_N\) 种不同的方法，那么完成这件事情共有 \(M_1 \times M_2 \times \cdots \times M_N\) 种不同的方法。
\end{itemize}

\begin{itemize}
  \item 从 \(n\) 个不同的元素中任取 \(m\) 个元素，按照一定顺序排成一列，叫做从 \(n\) 个不同元素中取出 \(m\) 个元素的一个排列。
\end{itemize}

\begin{itemize}
  \item \(A_n^m = n(n-1)\cdots(n-m+1) = \frac{n!}{(n-m)!}\) (\(m \leq n, n, m \in \mathbb{N}\))
\end{itemize}

\begin{itemize}
  \item 从 \(n\) 个不同的元素中任取 \(m\) 个元素并成一组，叫做从 \(n\) 个不同元素中取出 \(m\) 个元素的一个组合。
\end{itemize}

\begin{itemize}
  \item \(C_n^m = \frac{A_n^m}{A_m^m} = \frac{n(n-1)\cdots(n-m+1)}{m!} = \frac{n!}{m!(n-m)!}\)
  \item \(C_n^m = C_n^{n-m}\)
  \item \(C_{n-1}^{m-1} + C_n^m = C_{n+1}^m\)
\end{itemize}

\begin{itemize}
  \item \((a + b)^n = C_n^0 a^n + C_n^1 a^{n-1} b + C_n^2 a^{n-2} b^2 + \cdots + C_n^r a^{n-r} b^r + \cdots + C_n^n b^n\)
\end{itemize}

\begin{itemize}
  \item \(T_{r+1} = C_n^r a^{n-r} b^r\) (\(r = 0, 1, \ldots, n\))
\end{itemize}

\begin{itemize}
  \item 对于两个非零向量 \(\vec{a}\) 和 \(\vec{b}\)，若 \(\langle \vec{a}, \vec{b} \rangle = \frac{\pi}{2}\)，则向量 \(\vec{a}\)，\(\vec{b}\) 互相垂直，记作 \(\vec{a} \perp \vec{b}\)。
\end{itemize}

\begin{itemize}
  \item 如果随机试验可能出现的结果可以用一个变量 \(X\) 来表示，并且 \(X\) 是随着试验的结果的不同而变化，那么这样的变量叫做随机变量。随机变量常用大写字母 \(X\)、\(Y\) 等或希腊字母 \(\xi\)、\(\eta\) 等表示。
\end{itemize}

\begin{itemize}
  \item 在上面的射击、产品检验等例子中，对于随机变量 \(X\) 可能取的值，我们可以按一定次序一一列出，这样的随机变量叫做离散型随机变量。
\end{itemize}

\begin{itemize}
  \item 一般的，设离散型随机变量 \(X\) 可能取的值为 \(x_1, x_2, \ldots, x_i, \ldots, x_n\)。\(X\) 取每一个值 \(x_i\)（\(i=1, 2, \ldots\)）的概率 \(P(\xi = x_i) = P_i\)，则称表为离散型随机变量 \(X\) 的概率分布，简称分布列。
  \item \begin{tabular}{|c|c|c|c|c|c|}
    \hline
    \(X\) & \(x_1\) & \(x_2\) & \ldots & \(x_i\) & \ldots & \(x_n\) \\
    \hline
    \(P\) & \(p_1\) & \(p_2\) & \ldots & \(p_i\) & \ldots & \(p_n\) \\
    \hline
  \end{tabular}
\end{itemize}

\begin{itemize}
  \item ① \(p_i \geq 0\), \(i=1, 2, \ldots\);
  \item ② \(p_1 + p_2 + \cdots + p_n = 1\).
\end{itemize}

\begin{itemize}
  \item 如果随机变量 \(X\) 的分布列为：
  \item \begin{tabular}{|c|c|c|}
    \hline
    \(X\) & 1 & 0 \\
    \hline
    \(P\) & \(p\) & \(q\) \\
    \hline
  \end{tabular}
  \item 其中 \(0 < p < 1\), \(q = 1 - p\)，则称离散型随机变量 \(X\) 服从参数 \(p\) 的二点分布。
\end{itemize}

\begin{itemize}
  \item 一般地，设总数为 \(N\) 件的两类物品，其中一类有 \(M\) 件，从所有物品中任取 \(n\)（\(n \leq N\)）件，这 \(n\) 件中所含这类物品件数 \(X\) 是一个离散型随机变量，则它取值为 \(k\) 时的概率为：
  \item \(P(X = k) = \frac{C_M^k C_{N-M}^{n-k}}{C_N^n}\)（\(k = 0, 1, 2, \ldots, m\)）,
  \item 其中 \(m = \min\{M, n\}\)，且 \(n \leq N\), \(M \leq N\), \(n, M, N \in \mathbb{N}^*\)。
\end{itemize}

\begin{itemize}
  \item 对任意事件 \(A\) 和事件 \(B\)，在已知事件 \(A\) 发生的条件下事件 \(B\) 发生的概率，叫做条件概率。记作 \(P(B|A)\)，读作 \(A\) 发生的条件下 \(B\) 的概率。
\end{itemize}

\begin{itemize}
  \item \(P(B|A) = \frac{P(AB)}{P(A)}\), \(P(A) > 0\).
\end{itemize}

\begin{itemize}
  \item 事件 \(A\)（或 \(B\)）是否发生对事件 \(B\)（或 \(A\)）发生的概率没有影响，这样的两个事件叫做相互独立事件。
  \item \(P(A \cdot B) = P(A) \cdot P(B)\)
\end{itemize}

\begin{itemize}
  \item 在同等条件下进行的，各次之间相互独立的一种试验。
\end{itemize}

\begin{itemize}
  \item 设在 \(n\) 次独立重复试验中某个事件 \(A\) 发生的次数，\(A\) 发生次数 \(\xi\) 是一个随机变量。如果在一次试验中某事件发生的概率是 \(p\)，事件 \(A\) 不发生的概率为 \(q=1-p\)，那么在 \(n\) 次独立重复试验中：
    \[
    P(\xi = k) = C_n^k p^k q^{n-k}
    \]
    （其中 \(k=0, 1, \ldots, n\)，\(q=1-p\)）
  \item 于是可得随机变量 \(\xi\) 的概率分布如下：
  \item \begin{tabular}{|c|c|c|c|c|c|}
    \hline
    \(\xi\) & 0 & 1 & \ldots & \(k\) & \ldots & \(n\) \\
    \hline
    \(P\) & \(C_n^0 p^0 q^n\) & \(C_n^1 p^1 q^{n-1}\) & \ldots & \(C_n^k p^k q^{n-k}\) & \ldots & \(C_n^n p^n q^0\) \\
    \hline
  \end{tabular}
  \item 这样的随机变量 \(\xi\) 服从二项分布，记作 \(\xi \sim B(n, p)\)，其中 \(n, p\) 为参数。
\end{itemize}

\begin{itemize}
  \item 一般地，若离散型随机变量 \(\xi\) 的概率分布为：
  \item \begin{tabular}{|c|c|c|c|c|c|}
    \hline
    \(\xi\) & \(x_1\) & \(x_2\) & \ldots & \(x_i\) & \ldots \\
    \hline
    \(P\) & \(p_1\) & \(p_2\) & \ldots & \(p_i\) & \ldots \\
    \hline
  \end{tabular}
  \item 则称 \(E \xi = x_1 p_1 + x_2 p_2 + \cdots + x_i p_i + \cdots\) 为 \(\xi\) 的数学期望或平均数、均值，数学期望又简称为期望。
\end{itemize}

\begin{itemize}
  \item \(D(\xi) = (x_1 - E \xi)^2 \cdot P_1 + (x_2 - E \xi)^2 \cdot P_2 + \cdots + (x_n - E \xi)^2 \cdot P_n\) 叫随机变量 \(\xi\) 的均方差，简称方差。
\end{itemize}

\begin{itemize}
  \item \begin{tabular}{|c|c|c|}
    \hline
    & 期望 & 方差 \\
    \hline
    两点分布 & \(E \xi = p\) & \(D \xi = pq\), \(q = 1 - p\) \\
    \hline
    二项分布, \(\xi \sim B(n, p)\) & \(E \xi = np\) & \(D \xi = npq\), \(q = 1 - p\) \\
    \hline
  \end{tabular}
\end{itemize}

